async function createQ(data) {
  const ci = KEYS.indexOf(data.ans);
  await p.question.create({
    data: {
      content: data.q,
      subjectId: 'sub-khoahoc',
      gradeId: 'grade-5',
      topicId: data.topicId,
      difficulty: 'HARD',
      questionType: 'MULTIPLE_CHOICE',
      status: 'ACTIVE',
      createdById: 'user-admin',
      explanation: data.exp,
      options: { create: data.opts.map((text, i) => ({ optionKey: KEYS[i], content: text, isCorrect: i === ci, sortOrder: i })) },
    },
  });
}

